import fs from 'node:fs';
import path from 'node:path';
import { gunzipSync } from 'node:zlib';
const files = JSON.parse(gunzipSync(Buffer.from('', 'base64')).toString('utf8'));
for (const [relative, content] of Object.entries(files)) {
  const target = path.resolve(relative);
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, content, 'utf8');
  console.log(`wrote ${relative}`);
}
function read(file) { return fs.readFileSync(file, 'utf8'); }
function write(file, value) { fs.writeFileSync(file, value, 'utf8'); console.log(`patched ${file}`); }
function replaceOnce(file, from, to) {
  const source = read(file);
  const count = source.split(from).length - 1;
  if (count !== 1) throw new Error(`${file}: expected one marker, got ${count}`);
  write(file, source.replace(from, to));
}
